import type { UserRole } from '../users/user.types.js';

/** US02 seam event: emitted after the creating transaction commits. */
export const ACCOUNT_CREATED = 'account.created' as const;

export interface AccountCreatedPayload {
  userId: string;
  email: string;
  fullName: string;
  role: UserRole;
  occurredAt: Date;
  /** Request id, or a randomUUID generated by US02. */
  correlationId: string;
}
